{
  "claims": [
    {
      "claim": "Au niveau fédéral en Suisse, une initiative populaire peut proposer une révision totale ou partielle de la Constitution fédérale.",
      "verdict": "supported"
    },
    {
      "claim": "Il n'existe pas d'initiative fédérale pour amender ou introduire une loi.",
      "verdict": "supported"
    },
    {
      "claim": "Une initiative est invalide si elle viole l'unité de la forme, l'unité de la matière ou le droit international obligatoire.",
      "verdict": "supported"
    },
    {
      "claim": "Une initiative populaire peut être présentée sous forme de projet rédigé de toutes pièces ou sous forme de proposition générale.",
      "verdict": "supported"
    },
    {
      "claim": "Pour qu'une initiative soit soumise au vote populaire, elle doit recueillir au moins 100 000 signatures valables de citoyens suisses dans un délai de 18 mois.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Une initiative nécessite l'approbation de la double majorité (majorité des votants et majorité des cantons) pour être adoptée.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Une initiative ne peut pas violer les droits fondamentaux reconnus par le droit international public.",
      "verdict": "supported"
    },
    {
      "claim": "Une initiative doit porter sur un seul objet ou sur plusieurs objets étroitement liés.",
      "verdict": "supported"
    },
    {
      "claim": "Le texte de l'initiative doit être clair et précis, sans termes trop vagues ou ambigus.",
      "verdict": "supported"
    },
    {
      "claim": "L'initiative ne doit pas violer les principes fondamentaux de la Constitution fédérale tels que la démocratie, l'état de droit, la séparation des pouvoirs, la protection des droits fondamentaux.",
      "verdict": "supported"
    },
    {
      "claim": "L'initiative doit être réalisable et exécutable.",
      "verdict": "supported"
    },
    {
      "claim": "L'initiative doit respecter les règles de procédure établies par la loi sur les droits politiques.",
      "verdict": "supported"
    }
  ],
